// static
bool StructTraits<::omnibox_everywhere::mojom::ComposeboxInitialState::DataView, ::omnibox_everywhere::mojom::ComposeboxInitialStatePtr>::Read(
    ::omnibox_everywhere::mojom::ComposeboxInitialState::DataView input,
    ::omnibox_everywhere::mojom::ComposeboxInitialStatePtr* output) {
  bool success = true;
  ::omnibox_everywhere::mojom::ComposeboxInitialStatePtr result(::omnibox_everywhere::mojom::ComposeboxInitialState::New());
  
      if (success && !input.ReadTool(&result->tool))
        success = false;
      if (success && !input.ReadModel(&result->model))
        success = false;
      if (success && !input.ReadTab(&result->tab))
        success = false;
      if (success && !input.ReadFileToken(&result->file_token))
        success = false;
      if (success && !input.ReadFileInfo(&result->file_info))
        success = false;
      if (success)
        result->is_pending_screenshot = input.is_pending_screenshot();
  *output = std::move(result);
  return success;
}

